<?php use CmuLms\View; $title='Course activity'; include __DIR__.'/../layout/header.php'; ?>
<section class="hero"><span><?=View::e($course['code'])?> · Live monitoring</span><h1><?=View::e($course['title'])?></h1><p>Student presence and assessment progress from the database.</p></section>
<section class="card"><h2>Student activity</h2><div style="overflow-x:auto"><table><thead><tr><th>Student</th><th>School ID</th><th>Status</th><th>Last login</th><th>Last logout</th><th>Last activity</th></tr></thead><tbody>
<?php foreach($students as $student): ?><tr><td><?=View::e($student['name'])?></td><td><?=View::e($student['id_number'])?></td><td><span class="badge"><?=$student['online']?'Online':'Offline'?></span></td><td><?=View::e($student['last_login_at']??'Never')?></td><td><?=View::e($student['last_logout_at']??'Never')?></td><td><?=View::e($student['last_activity_at']??'Never')?></td></tr><?php endforeach; ?>
<?php if(!$students): ?><tr><td colspan="6">No enrolled students.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card"><h2>Quiz progress</h2><div style="overflow-x:auto"><table><thead><tr><th>Student</th><th>Quiz</th><th>Status</th><th>Progress</th><th>Minutes taken</th><th>Time remaining</th><th>Violations</th><th>Started</th></tr></thead><tbody>
<?php foreach($progress as $item): ?><tr><td><?=View::e($item['student_name'])?></td><td><?=View::e($item['exam_title'])?></td><td><span class="badge"><?=View::e($item['status'])?></span></td><td><?=View::e($item['answers_saved'])?> / <?=View::e($item['question_count'])?> (<?=View::e($item['progress_percent'])?>%)</td><td><?=View::e($item['minutes_taken'])?></td><td><?=$item['status']==='in_progress'?floor($item['time_remaining']/60).':'.str_pad((string)($item['time_remaining']%60),2,'0',STR_PAD_LEFT):'—'?></td><td><?=View::e($item['violation_count']??0)?></td><td><?=View::e($item['started_at'])?></td></tr><?php endforeach; ?>
<?php if(!$progress): ?><tr><td colspan="8">No quiz attempts have been recorded.</td></tr><?php endif; ?></tbody></table></div></section>
<p><a class="btn" href="?route=course&amp;id=<?=View::e($course['id'])?>">Back to course</a></p>
